use super::*;
fn fixture()->(tempfile::TempDir,Db){let t=tempfile::tempdir().unwrap();let db=db::open(&t.path().join("library.sqlite")).unwrap();db.lock().unwrap().execute_batch("INSERT INTO roots(id,path,label) VALUES('root','generated','Source');INSERT INTO resources(id,root_id,relative_path,title,kind) VALUES('r','root','Bundle','Bundle','directory');INSERT INTO files(id,root_id,path,relative_path,size,mtime,ext,seen_job) VALUES('f','root','Bundle/Story.zip','Bundle/Story.zip',1,'1','zip','');INSERT INTO resource_files VALUES('r','f');").unwrap();(t,db)}
fn input(ids:&[&str])->Create{Create{revision:1,works:ids.iter().map(|s|s.to_string()).collect(),query:"物語".into(),rationale:"Own Japanese title".into()}}
fn candidates()->Vec<Value>{vec![json!({"id":"v1","title":"Story","alttitle":"物語","developers":[{"name":"Key","original":"キー"}],"released":"2004-04-28"}),json!({"id":"v2","title":"Second Story","aliases":["物語"]})]}
fn propose(db:&Db,v:&Create)->Value{let mut c=db.lock().unwrap();let tx=c.transaction().unwrap();let result=store(&tx,"r",v,"mcp:test",&candidates()).unwrap();tx.commit().unwrap();result}
fn count(c:&Connection,table:&str)->i64{c.query_row(&format!("SELECT count(*) FROM {table}"),[],|r|r.get(0)).unwrap()}
#[test]fn deterministic_own_names_and_corroboration(){
 let work=json!({"id":"v18852","title":"Amatsutsumi","alttitle":"アマツツミ","titles":[{"lang":"ja","title":"アマツツミ","latin":"Amatsutsumi"}],"aliases":["天津罪"],"developers":[{"name":"Purple software","original":"パープルソフトウェア"}],"released":"2016-07-29"});
 for (folder,query,expected) in [("[Purple software] unknown","アマツツミ",true),("unknown","天津罪",true),("unknown","does not match",false),("[Key] unknown","アマツツミ",false),("[160729] unknown","Amatsutsumi",true),("[160730] unknown","Amatsutsumi",false)]{let input=matching::prepare(folder,&[]).unwrap();assert_eq!(verify(&input,query,&work)["verified"],expected,"{folder} / {query}");}
 let input=matching::prepare("[160729][Purple software] アマツツミ.zip",&[]).unwrap();assert_eq!(verify(&input,"different query",&work)["verified"],true);
 let mut release_only=work.clone();release_only["release_matches"]=json!([{"title":"Release alias"}]);assert_eq!(verify(&matching::prepare("unknown",&[]).unwrap(),"Release alias",&release_only)["verified"],false);
 let titles=json!({"id":"v1","title":"Foreign","titles":[{"title":"中文標題","latin":"Other"}]});assert_eq!(verify(&matching::prepare("unknown",&[]).unwrap(),"中文標題",&titles)["verified"],true);
}
#[test]fn replacement_revision_and_manual_bind_invalidate(){let(_t,db)=fixture();let first=propose(&db,&input(&["v1"]));let second=propose(&db,&input(&["v2"]));{let c=db.lock().unwrap();assert_eq!(get(&c,first["id"].as_str().unwrap()).unwrap()["state"],"dismissed");assert_eq!(open(&c,"r").unwrap(),second);c.execute("UPDATE resources SET revision=revision+1",[]).unwrap();assert!(open(&c,"r").unwrap().is_null());assert_eq!(get(&c,second["id"].as_str().unwrap()).unwrap()["state"],"stale");}
 let mut v=input(&["v1"]);v.revision=2;let third=propose(&db,&v);db.lock().unwrap().execute("INSERT INTO works(id,title,original_title) VALUES('w','Manual','Manual')",[]).unwrap();editions::bind_primary(&db,"r","w","Unclassified edition",2).unwrap();assert_eq!(get(&db.lock().unwrap(),third["id"].as_str().unwrap()).unwrap()["state"],"stale");assert!(store(&db.lock().unwrap(),"r",&v,"mcp:test",&candidates()).is_err());}
#[test]fn single_and_multiple_confirmation_share_manual_history_and_rollback(){for ids in [vec!["v1"],vec!["v1","v2"]]{let(_t,db)=fixture();let v=input(&ids);let s=propose(&db,&v);let id=s["id"].as_str().unwrap();
 {let c=db.lock().unwrap();assert_eq!(count(&c,"works"),0);assert_eq!(count(&c,"resource_bindings"),0);}
 assert!(bind(&db,id,9,false,&candidates()).is_err());{let c=db.lock().unwrap();assert_eq!(count(&c,"works"),0);assert_eq!(count(&c,"resource_history"),0);assert_eq!(get(&c,id).unwrap()["state"],"open");c.execute_batch("CREATE TRIGGER reject_confirmation BEFORE INSERT ON events BEGIN SELECT RAISE(ABORT,'test failure'); END;").unwrap();}
 assert!(bind(&db,id,1,false,&candidates()).is_err());{let c=db.lock().unwrap();assert_eq!(count(&c,"works"),0);assert_eq!(count(&c,"resource_bindings"),0);assert_eq!(count(&c,"resource_history"),0);assert_eq!(get(&c,id).unwrap()["state"],"open");c.execute_batch("DROP TRIGGER reject_confirmation").unwrap();}
 bind(&db,id,1,false,&candidates()).unwrap();{let c=db.lock().unwrap();assert_eq!(count(&c,"works"),ids.len() as i64);let bindings=editions::bindings(&c,"r").unwrap();assert_eq!(bindings.len(),ids.len());assert!(bindings.iter().all(|b|b.role=="main"&&b.release_id.is_none()));assert_eq!(c.query_row("SELECT w.vndb_id FROM resources r JOIN works w ON w.id=r.work_id",[],|r|r.get::<_,String>(0)).unwrap(),"v1");assert_eq!(get(&c,id).unwrap()["state"],"confirmed");assert_eq!(count(&c,"resource_history"),1);assert_eq!(c.query_row("SELECT code FROM events ORDER BY seq DESC LIMIT 1",[],|r|r.get::<_,String>(0)).unwrap(),"manual.bind");}
 assert!(crate::automatch::kick(&db,true).unwrap().is_none());assert!(bind(&db,id,1,false,&candidates()).is_err());}}
#[test]fn unchanged_rescan_keeps_suggestion_changed_and_removed_files_stale(){let t=tempfile::tempdir().unwrap();let source=t.path().join("source");std::fs::create_dir(&source).unwrap();let file=source.join("Story.zip");std::fs::write(&file,"first").unwrap();let db=db::open(&t.path().join("library.sqlite")).unwrap();db.lock().unwrap().execute("INSERT INTO roots(id,path,label) VALUES('root',?1,'Source')",[source.to_str().unwrap()]).unwrap();let scan=||{let job=crate::scan::create(&db,crate::scan::ScanSpec{root_id:"root".into(),scope:"".into(),exclude:vec![]}).unwrap();crate::scan::run(db.clone(),job);};scan();let(rid,revision):(String,i64)=db.lock().unwrap().query_row("SELECT id,revision FROM resources",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();let mut v=input(&["v1"]);v.revision=revision;let s=store(&db.lock().unwrap(),&rid,&v,"test",&candidates()).unwrap();scan();assert_eq!(open(&db.lock().unwrap(),&rid).unwrap(),s);std::fs::write(&file,"changed content").unwrap();scan();assert!(open(&db.lock().unwrap(),&rid).unwrap().is_null());v.revision=db.lock().unwrap().query_row("SELECT revision FROM resources",[],|r|r.get(0)).unwrap();let s=store(&db.lock().unwrap(),&rid,&v,"test",&candidates()).unwrap();std::fs::remove_file(file).unwrap();scan();assert_eq!(get(&db.lock().unwrap(),s["id"].as_str().unwrap()).unwrap()["state"],"stale");}
#[test]fn schema_46_upgrade_backs_up_preserves_catalog_and_reopens(){let(t,db)=fixture();let path=t.path().join("library.sqlite");{let c=db.lock().unwrap();c.execute_batch("DROP TRIGGER suggestion_revision;DROP TABLE match_suggestions;PRAGMA user_version=46;UPDATE settings SET value='46' WHERE key='schema_version';").unwrap();}drop(db);let db=db::open(&path).unwrap();{let c=db.lock().unwrap();assert_eq!(count(&c,"resources"),1);assert_eq!(count(&c,"match_suggestions"),0);assert_eq!(c.query_row("PRAGMA user_version",[],|r|r.get::<_,i64>(0)).unwrap(),47);assert_eq!(c.query_row("SELECT value FROM settings WHERE key='schema_version'",[],|r|r.get::<_,String>(0)).unwrap(),"47");assert_eq!(count(&c,"pragma_foreign_key_check"),0);}let s=propose(&db,&input(&["v1"]));drop(db);let db=db::open(&path).unwrap();assert_eq!(open(&db.lock().unwrap(),"r").unwrap(),s);let backups=std::fs::read_dir(t.path().join("migration-backups")).unwrap().collect::<Result<Vec<_>,_>>().unwrap();assert_eq!(backups.len(),1);let saved=Connection::open(backups[0].path()).unwrap();assert_eq!(saved.query_row("PRAGMA user_version",[],|r|r.get::<_,i64>(0)).unwrap(),46);assert_eq!(saved.query_row("SELECT count(*) FROM sqlite_schema WHERE name='match_suggestions'",[],|r|r.get::<_,i64>(0)).unwrap(),0);}

async fn http(a:&App,transport:crate::Transport,role:&str,credential:&str,method:&str,path:&str,body:Value)->(StatusCode,Value){use tower::ServiceExt;let host=if transport==crate::Transport::Lan{"192.168.50.154:14830"}else{"localhost"};let mut r=axum::http::Request::builder().method(method).uri(path).header("Host",host).header("Origin",format!("{}://{host}",if transport==crate::Transport::Lan{"https"}else{"http"})).header("Content-Type","application/json");r=if role=="web"{r.header("Cookie",credential)}else{r.header("Authorization",format!("Bearer {credential}"))};let response=crate::router_for(a.clone(),transport).oneshot(r.body(axum::body::Body::from(body.to_string())).unwrap()).await.unwrap();let status=response.status();let bytes=axum::body::to_bytes(response.into_body(),1024*1024).await.unwrap();(status,serde_json::from_slice(&bytes).unwrap_or(Value::Null))}
#[tokio::test]async fn role_transport_suggestion_matrix_and_web_path_projection(){
 for transport in [crate::Transport::Loopback,crate::Transport::Lan]{for role in ["owner","desktop","web"]{let(_t,a,desktop,cookie)=crate::web_projection::tests::fixture();let credential=match role{"owner"=>&a.token,"desktop"=>&desktop,_=>&cookie};let allowed=role!="web"&&!(role=="owner"&&transport==crate::Transport::Lan);let denied_owner=role=="owner"&&transport==crate::Transport::Lan;
 {let c=a.db.lock().unwrap();c.execute_batch("DELETE FROM resource_bindings;UPDATE resources SET work_id=NULL;").unwrap();}
 let mut work=candidates()[0].clone();work["id"]=json!("v910001");matching::cache_work_for_test(work.clone()).await;
 let (status,created)=http(&a,transport,role,credential,"POST","/api/resources/resource/suggestions",json!({"revision":1,"works":["v910001"],"query":"物語","rationale":"Review /private/ZZ-SUGGESTION-PATH/game"})).await;assert_eq!(status,if allowed{200}else{403},"{role} {transport:?}");
 let s=if allowed{created}else{let c=a.db.lock().unwrap();assert_eq!(count(&c,"match_suggestions"),0);store(&c,"resource",&Create{works:vec!["v910001".into()],rationale:"Review /private/ZZ-SUGGESTION-PATH/game".into(),..input(&[])},"mcp:/private/ZZ-SUGGESTION-PATH",&[work]).unwrap()};let id=s["id"].as_str().unwrap();
 for path in ["/api/suggestions","/api/resources/resource/suggestions","/api/resources/page","/api/resources"]{let(status,value)=http(&a,transport,role,credential,"GET",path,Value::Null).await;assert_eq!(status,if denied_owner{403}else{200},"{role} {transport:?} {path}");if role=="web"{assert!(!value.to_string().contains("ZZ-SUGGESTION-PATH"));assert!(!value.to_string().contains("ZZ-SECRET-ROOT"));}if path=="/api/resources/page"&&!denied_owner{assert_eq!(value["items"][0]["suggestion"]["id"],id);}}
 let(status,_)=http(&a,transport,role,credential,"POST",&format!("/api/suggestions/{id}/confirm"),json!({"revision":999})).await;assert_eq!(status,if allowed{409}else{403});
 let(status,value)=http(&a,transport,role,credential,"POST","/api/suggestions/batch-confirm",json!({"ids":[id],"revisions":[999]})).await;assert_eq!(status,if allowed{200}else{403});if allowed{assert_eq!(value["results"][0]["confirmed"],false);}
 let(status,_)=http(&a,transport,role,credential,"POST",&format!("/api/suggestions/{id}/dismiss"),json!({})).await;assert_eq!(status,if allowed{200}else{403});assert_eq!(count(&a.db.lock().unwrap(),"resource_bindings"),0);
 }}
}
#[tokio::test]async fn batch_skips_unverified_and_reports_each_id_with_atomic_success(){let(_t,a,_,_)=crate::web_projection::tests::fixture();{let c=a.db.lock().unwrap();c.execute_batch("DELETE FROM resource_bindings;UPDATE resources SET work_id=NULL;INSERT INTO resources(id,root_id,relative_path,title,kind) VALUES('other','root','Unknown','Unknown','archive');INSERT INTO files(id,root_id,path,relative_path,size,mtime,ext,seen_job) VALUES('otherfile','root','Unknown/file.bin','Unknown/file.bin',1,'1','bin','');INSERT INTO resource_files VALUES('other','otherfile');").unwrap();}
 let work=json!({"id":"v910002","title":"Verified Game","alttitle":"物語"});matching::cache_work_for_test(work.clone()).await;
 let yes=store(&a.db.lock().unwrap(),"resource",&Create{works:vec!["v910002".into()],..input(&[])},"test",&[work.clone()]).unwrap();let no=store(&a.db.lock().unwrap(),"other",&Create{works:vec!["v910002".into()],query:"Nothing matches".into(),..input(&[])},"test",&[work]).unwrap();assert_eq!(yes["verified"],true);assert_eq!(no["verified"],false);
 let(status,result)=http(&a,crate::Transport::Loopback,"owner",&a.token,"POST","/api/suggestions/batch-confirm",json!({"ids":[no["id"],yes["id"],"missing"],"revisions":[1,1,1]})).await;assert_eq!(status,200);assert_eq!(result["results"][0]["confirmed"],false);assert_eq!(result["results"][1]["state"],"confirmed");assert_eq!(result["results"][2]["confirmed"],false);assert_eq!(count(&a.db.lock().unwrap(),"resource_bindings"),1);assert_eq!(get(&a.db.lock().unwrap(),no["id"].as_str().unwrap()).unwrap()["state"],"open");
 // Individual confirmation deliberately permits an unverified proposal, as a manual decision.
 let(status,result)=http(&a,crate::Transport::Loopback,"owner",&a.token,"POST",&format!("/api/suggestions/{}/confirm",no["id"].as_str().unwrap()),json!({"revision":1})).await;assert_eq!(status,200,"{result}");assert_eq!(count(&a.db.lock().unwrap(),"resource_bindings"),2);assert_eq!(count(&a.db.lock().unwrap(),"works"),2);
}
#[test]fn regroup_invalidates_open_suggestion(){let(_t,db)=fixture();let s=propose(&db,&input(&["v1"]));let selection=crate::membership::Selection{revision:1,file_ids:vec!["f".into()],target_id:None,target_revision:None,title:"New group".into()};let preview=crate::membership::preview(&db,"r",&selection).unwrap();crate::membership::apply(&db,"r",&selection,preview["digest"].as_str().unwrap()).unwrap();assert_eq!(get(&db.lock().unwrap(),s["id"].as_str().unwrap()).unwrap()["state"],"stale");}
#[tokio::test]async fn suggestion_pages_and_review_payload_keep_open_state(){let(_t,a,_,_)=crate::web_projection::tests::fixture();{let c=a.db.lock().unwrap();c.execute_batch("DELETE FROM resource_bindings;UPDATE resources SET work_id=NULL;").unwrap();let s=store(&c,"resource",&input(&["v1"]),"test",&candidates()).unwrap();for n in 0..61{c.execute("INSERT INTO resources(id,root_id,relative_path,title,kind) VALUES(?1,'root',?1,?1,'archive')",[format!("page{n}")]).unwrap();c.execute("INSERT INTO match_suggestions SELECT ?1,?1,1,works,query,rationale,source,verified,verification,'open',created,updated FROM match_suggestions WHERE id=?2",params![format!("page{n}"),s["id"].as_str()]).unwrap();}crate::issues::reconcile(&c).unwrap();}
 let(status,first)=http(&a,crate::Transport::Loopback,"owner",&a.token,"GET","/api/suggestions",Value::Null).await;assert_eq!(status,200);assert_eq!(first["items"].as_array().unwrap().len(),60);let cursor=first["next"].as_i64().unwrap();let(_,last)=http(&a,crate::Transport::Loopback,"owner",&a.token,"GET",&format!("/api/suggestions?before={cursor}"),Value::Null).await;assert_eq!(last["items"].as_array().unwrap().len(),2);assert!(last["next"].is_null());
 let(_,issues)=http(&a,crate::Transport::Loopback,"owner",&a.token,"GET","/api/issues",Value::Null).await;assert!(issues["items"].as_array().unwrap().iter().any(|i|i["resource_id"]=="resource"&&i["suggestion"]["state"]=="open"));
}
